// ---------- verification: cached vs uncached ----------
function verifyParity(model, ids) {
  const full = forwardFull(model, ids);
  const cache = createCache(model);
  let worst = 0, worstAt = null, worstKind = 'logit';
  const perPos = [];
  for (let t = 1; t <= ids.length; t++) {
    const prefix = ids.slice(0, t);
    const inc = forwardCached(model, prefix, cache);
    const i = t - 1;
    let dLogit = 0, dProb = 0;
    for (let v = 0; v < model.V; v++) {
      dLogit = Math.max(dLogit, Math.abs(inc.logits[i][v] - full.logits[i][v]));
      dProb = Math.max(dProb, Math.abs(inc.probs[i][v] - full.probs[i][v]));
    }
    const d = Math.max(dLogit, dProb);
    if (d > worst) { worst = d; worstAt = [i, dLogit >= dProb ? 'logit' : 'prob']; }
    perPos.push({ pos: i, maxDiff: d });
  }
  return { maxAbsDiff: worst, worstAt, ok: worst < 1e-9, full, perPos };
}

