    }
    const p1 = inc.probs[i], p2 = full.probs[i];
    for (let v = 0; v < model.V; v++) {
      const d = Math.abs(p1[v] - p2[v]);
      if (d > worst) { worst = d; worstAt = [i, v]; }
    }
    perPos.push({ pos: i, maxDiff: 0 });
  }
  return { maxAbsDiff: worst, worstAt, ok: worst < 1e-9, full, perPos };
}

