// row vector @ matrix (matrix stored row-major, shape [nIn][nOut])
// y[e] = sum_d x[d] * M[d*nOut + e], ascending d
function matvec(x, M, nIn, nOut) {
  const y = new Array(nOut).fill(0);
  for (let d = 0; d < nIn; d++) {
    const xd = x[d];
    const base = d * nOut;
    for (let e = 0; e < nOut; e++) y[e] += xd * M[base + e];
  }
  return y;
}

