function matvec(x, M, nIn, nOut) {
  const y = new Array(nOut).fill(0);
  for (let d = 0; d < nIn; d++) {
    const xd = x[d];
    if (xd === 0) { /* still accumulate for exact parity with numpy? numpy does full MACs.
                       To be safe against -0/0 differences we do not skip zeros. */
    }
    const base = d * nOut;
    for (let e = 0; e < nOut; e++) y[e] += xd * M[base + e];
  }
  return y;
}

