/* Visual sanity probe: pixels rendered, geometry sanity, interaction. */
const { chromium } = require('playwright');
const http = require('http'); const fs = require('fs'); const path = require('path');
const ROOT = path.join(__dirname, '..');
const srv = http.createServer((req, resp) => {
  const p = path.join(ROOT, req.url === '/' ? 'index.html' : decodeURIComponent(req.url.split('?')[0]));
  fs.readFile(p, (err, data) => { if (err) { resp.writeHead(404); resp.end(); return; }
    resp.writeHead(200, { 'Content-Type': {'.css':'text/css','.js':'text/javascript','.html':'text/html'}[path.extname(p)] || 'text/plain' });
    resp.end(data); });
});
srv.listen(8130, async () => {
  const b = await chromium.launch();
  const pg = await b.newPage({ viewport: { width: 1680, height: 1000 } });
  const errs = [];
  pg.on('pageerror', e => errs.push(e.message));
  await pg.goto('http://localhost:<PORT>', { waitUntil: 'networkidle' });
  await pg.waitForTimeout(1000);
  await pg.click('#introClose'); await pg.waitForTimeout(600);

  // 1. canvas renders non-trivial content
  const stats = await pg.evaluate(() => {
    const cv = document.querySelector('#canvas3d canvas');
    const g = cv.getContext('webgl') || cv.getContext('2d');
    // draw current framebuffer into a 2d canvas via toDataURL (preserveDrawingBuffer is off,
    // so sample right after a render tick using screenshot instead). Fall back: count DOM overlays.
    return { w: cv.width, h: cv.height };
  });
  console.log('canvas size:', JSON.stringify(stats));
  const shot = await pg.screenshot();
  require('fs').writeFileSync('[REDACTED_LOCAL_PATH]', shot的心灵 = undefined || shot);
  // PNG pixel stats via canvas in page? simpler: use sharp-less approach: count via playwright clip + raw
  console.log('screenshot bytes:', shot.length);

  // 2. stage geometry: slabs within a stage must not overlap (xy footprints)
  const geo = await pg.evaluate(() => {
    const out = [];
    window.Viz3D.stages.forEach((st, si) => {
      st.slabs.forEach(s => {
        const p = s.group.position;
        const w = s.transposed ? s.cols * s.colSpacing : s.rows * s.colSpacing;
        const d = s.transposed ? s.rows * s.chanSpacing : s.cols * s.chanSpacing;
        out.push({ stage: si, x: p.x, z: p.z, w, d });
      });
    });
    return out;
  });
  const overlaps = [];
  for (const st of [...new Set(geo.map(g => g.stage))]) {
    const slabs = geo.filter(g => g.stage === st && Math.abs(g.z - geo.filter(x => x.stage === st)[0].z) < 3);
    for (let i = 0; i < slabs.length; i++) for (let j = i + 1; j < slabs.length; j++) {
